cssCode:
.orbit-wrap { position: relative; width: 120px; height: 120px; }
.orbit-ring {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  border-radius: 50%; border: 3px solid transparent;
  border-top-color: #00ffcc; border-bottom-color: #ff00ff;
  animation: spinOrbit 2s linear infinite;
  box-shadow: 0 0 20px rgba(0, 255, 204, 0.4), inset 0 0 20px rgba(255, 0, 255, 0.4);
}
.orbit-core {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  width: 20px; height: 20px; background: #fff; border-radius: 50%;
  box-shadow: 0 0 30px 10px #fff; animation: pulseCore 1.5s infinite alternate;
}
@keyframes spinOrbit { 100% { transform: rotate(360deg); } }
@keyframes pulseCore { 100% { transform: translate(-50%, -50%) scale(1.5); opacity: 0.8; } }

